mapper.select:

WHERE c.datasource_id = #{datasourceId}
  AND LOWER(table_meta.table_name) = LOWER(#{tableName})
ORDER BY c.column_name ASC, c.id ASC

mapper.update:
UPDATE column_info
column_name = #{columnName}, column_description = #{columnDescription}, semantic_type = #{semanticType}, is_visible = #{isVisible}, update_time = #{updateTime},
WHERE id = #{id}

UPDATE column_info
column_name = #{columnName}, physical_column_description = #{physicalColumnDescription}, type_name = #{typeName}, primary_key = #{primaryKey}, index_info = #{indexInfo}, physical_status = #{physicalStatus}, update_time = #{updateTime},
WHERE id = #{id}

UPDATE column_info
SET column_description = #{description}
WHERE id = #{id}
  AND (column_description IS NULL OR column_description = '')

UPDATE column_info
SET physical_status = 0,
    update_time = #{now}
WHERE id IN

    #{id}

  AND (physical_status IS NULL OR physical_status <> 0)

UPDATE column_info c INNER JOIN table_info t ON t.id = c.table_id SET c.column_description = c.physical_column_description, c.semantic_type = NULL, c.is_visible = 1, c.update_time = NOW() WHERE t.datasource_id = #{datasourceId} AND c.id IN
#{id}
AND (c.physical_status IS NULL OR c.physical_status <> 0)

mapper.delete:
DELETE c FROM column_info c INNER JOIN table_info t ON t.id = c.table_id WHERE t.datasource_id = #{datasourceId} AND c.id IN
#{id}
AND c.physical_status = 0
